        flag "-h --help" help="Print help" action=help builtin=#true
    }
}
cmd askpass help="Answer an OpenSSH askpass prompt" {
    long_help #"""
Answer an OpenSSH askpass prompt

OpenSSH runs the `SSH_ASKPASS` program with no extra arguments, so point it at a link to touchcue named `touchcue-askpass`. `touchcue askpass` passes every argument after it through unparsed.
"""#
    flag "-h --help" help="Print help" action=help builtin=#true
    arg "[MESSAGE]…" help="The prompt OpenSSH passes" required=#false double_dash=automatic var=#true
}
__USAGE_EOF__
    # stderr is discarded: a line that doesn't parse (`touchcue help <Tab>`) makes
    # complete-word fail, and its error would be printed over the prompt.
    # Complete the text before the cursor, as `$cur` holds it: with the cursor in `--out=a|X`
    # the value typed so far is `a`, not `aX`.
    words[cword]="$cur"
    # shellcheck disable=SC2207
	COMPREPLY=($(compgen -W "$(command usage complete-word --shell bash -f "$spec_file" --cword="$cword" -- "${words[@]}" 2>/dev/null)" -- "$cur"))
	# Readline only replaces the text after the last word break, so strip the part of
	# `$cur` up to its last `:` or `=` from each candidate (what __ltrim_colon_completions
	# does for `:` alone).
	local breaks="${COMP_WORDBREAKS//[^:=]/}"
	# An empty COMPREPLY is left alone: before bash 4.4 the rewrite below would turn it into
	# one empty candidate.
	if ((${#COMPREPLY[@]})) && [[ -n "$breaks" && "$cur" == *["$breaks"]* ]]; then
		local break_prefix="${cur%"${cur##*["$breaks"]}"}"
		COMPREPLY=("${COMPREPLY[@]#"$break_prefix"}")
	fi
    # shellcheck disable=SC2181
    if [[ $? -ne 0 ]]; then
        unset COMPREPLY
    fi
    return 0
}

if [[ "${BASH_VERSINFO[0]}" -eq 4 && "${BASH_VERSINFO[1]}" -ge 4 || "${BASH_VERSINFO[0]}" -gt 4 ]]; then
